<template><div><div class="row items-center justify-between q-mb-md"><div class="text-h5">保單內文</div><q-btn v-if="canCreate" color="primary" label="新增內文" icon="add" @click="$inertia.visit(route('admin.insurance-policy-contents.create'))" /></div><q-card><q-card-section><q-table :rows="contents" :columns="columns" row-key="id" flat wrap-cells><template #body-cell-content="props"><q-td :props="props" style="max-width:520px" class="ellipsis-2-lines">{{ props.value }}</q-td></template><template #body-cell-actions="props"><q-td :props="props"><q-btn v-if="canEdit" flat round dense icon="edit" @click="$inertia.visit(route('admin.insurance-policy-contents.edit',props.row.id))" /><q-btn v-if="canDelete" flat round dense color="negative" icon="delete" @click="selected=props.row;showDelete=true" /></q-td></template></q-table></q-card-section></q-card><q-dialog v-model="showDelete"><q-card><q-card-section class="text-h6">刪除保單內文</q-card-section><q-card-section>確定要刪除此內文片段嗎？</q-card-section><q-card-actions align="right"><q-btn flat label="取消" v-close-popup /><q-btn flat color="negative" label="刪除" @click="remove" /></q-card-actions></q-card></q-dialog></div></template>
<script setup lang="ts">
import { ref } from 'vue'; import { router } from '@inertiajs/vue3'; import AdminLayout from '../../Layouts/AdminLayout.vue'; import { useCan } from '../../Composables/useCan'
defineOptions({ layout: AdminLayout }); type Content={id:number;policy_label:string;content:string;page_from:number|null;page_to:number|null;sort_order:number;embedding_model:string}; defineProps<{contents:Content[]}>(); const {can:canCreate}=useCan('admin.insurance-policy-contents.create'); const {can:canEdit}=useCan('admin.insurance-policy-contents.edit'); const {can:canDelete}=useCan('admin.insurance-policy-contents.delete'); const selected=ref<Content|null>(null); const showDelete=ref(false); const columns=[{name:'policy_label',label:'保單',field:'policy_label',align:'left'},{name:'content',label:'內文摘要',field:'content',align:'left'},{name:'page_from',label:'起始頁',field:'page_from',align:'right'},{name:'page_to',label:'結束頁',field:'page_to',align:'right'},{name:'sort_order',label:'排序',field:'sort_order',align:'right'},{name:'embedding_model',label:'向量模型',field:'embedding_model',align:'left'},{name:'actions',label:'操作',field:'actions',align:'right'}]; const remove=()=>selected.value&&router.delete(route('admin.insurance-policy-contents.destroy',selected.value.id),{onSuccess:()=>showDelete.value=false})
